import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import * as fs from 'node:fs';
import { spawn } from 'node:child_process';
import { performance } from 'node:perf_hooks';
import * as os from 'node:os';

const directory = '/private/tmp/jobs53-negation-YOjRP6';
const executable = '/private/tmp/safe-bash-gnu-5.3-adjudication.0zMRKT/bash-5.3/bash';
const expectedBash = 'a0cfc1af0ff50f6b6e67c638979e2604f1c276c90116937fbaafcabb62ee2b40';
const expectedNode = '18e387c90ab8a8400183e8bdd396376e1e875b91b4c874b894dcade7b35bf572';
const expectedWrapper = '6a63272112393f50f5a994fea6adfa39950e6e81449acffbf639c880def1b5fb';
const expectedSources = [
  "796a2a887563388ef4d24ffc61ff6a52a5f0fb4cfb7b6e946ec4fbe1e14b1f23",
  "ae43695544ebebdf18f630a8da41ebbe01770072b63e3544f05ba0bfec16f397",
  "3082bbdb5ec1cc43917621b7d123e504eb8668752baafa840a2150814ebb5f5d",
  "19e575a8b1407cbca0da9c9daed61eb2f844ad68dfa50df0ed5173b5cf869b0c"
];
const environment = { LC_ALL: 'C', PATH: '/__ordinary_jobs_no_external_commands__' };
const save = (name, value) => fs.writeFileSync(`${directory}/${name}`, JSON.stringify(value, null, 2) + '\n', { flag: 'wx' });
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const describe = reason => ({ name: reason?.name, message: String(reason), stack: reason?.stack });
const identityKeys = ['dev', 'ino', 'size', 'mode', 'mtimeMs', 'ctimeMs'];

function admittedFile(path, maximum, retainText = false, retainedHandles) {
  assert.equal(fs.realpathSync(path), path, 'noncanonical input');
  const before = fs.lstatSync(path);
  assert.ok(before.isFile() && !before.isSymbolicLink() && before.size <= maximum, 'input kind or size refused');
  const handle = fs.openSync(path, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  let retained = false;
  try {
    const held = fs.fstatSync(handle);
    for (const key of identityKeys) assert.equal(held[key], before[key], `held input ${key} changed`);
    const digest = createHash('sha256');
    const buffer = Buffer.alloc(65536);
    const chunks = [];
    let total = 0;
    while (total < before.size) {
      const count = fs.readSync(handle, buffer, 0, Math.min(buffer.length, before.size - total), null);
      assert.ok(count > 0, 'input shrank');
      total += count;
      digest.update(buffer.subarray(0, count));
      if (retainText) chunks.push(Buffer.from(buffer.subarray(0, count)));
    }
    assert.equal(fs.readSync(handle, buffer, 0, 1, null), 0, 'input grew');
    const afterHeld = fs.fstatSync(handle);
    const afterPath = fs.lstatSync(path);
    assert.equal(fs.realpathSync(path), path);
    assert.ok(afterPath.isFile() && !afterPath.isSymbolicLink());
    for (const key of identityKeys) {
      assert.equal(afterHeld[key], before[key], `held input ${key} drift`);
      assert.equal(afterPath[key], before[key], `pathname input ${key} drift`);
    }
    if (retainedHandles) {
      retainedHandles.push({ handle, path, before });
      retained = true;
    }
    return {
      record: { path, sha256: digest.digest('hex'), ...Object.fromEntries(identityKeys.map(key => [key, before[key]])) },
      bytes: retainText ? Buffer.concat(chunks) : undefined,
    };
  } finally { if (!retained) fs.closeSync(handle); }
}

function authenticate(seal, retainedHandles) {
  const limits = { runner: 32768, outer: 32768, subjects: 32768, supervisor: 4096, bash: 4194304, node: 268435456, proposal: 32768, audit: 32768 };
  const paths = { runner: `${directory}/capture.mjs`, outer: `${directory}/outer.mjs`, subjects: `${directory}/subjects.json`, supervisor: `${directory}/supervisor.bash`, bash: executable, node: fs.realpathSync(process.execPath), proposal: '/private/tmp/jobs53-negation-YOjRP6/proposed-subjects.json', audit: '/private/tmp/jobs53-negation-YOjRP6/final.json' };
  const result = {};
  for (const [name, path] of Object.entries(paths)) {
    assert.equal(seal.bindings[name].path, path);
    const admitted = admittedFile(path, limits[name], name === 'subjects' || name === 'supervisor', retainedHandles);
    assert.equal(admitted.record.sha256, seal.bindings[name].sha256, `${name} seal mismatch`);
    result[name] = admitted;
  }
  assert.equal(result.bash.record.sha256, expectedBash);
  assert.equal(result.node.record.sha256, expectedNode);
  assert.equal(result.supervisor.record.sha256, expectedWrapper);
  return result;
}

function runCase(entry, wrapper, admission) {
  const start = performance.now();
  const events = [];
  const output = { 1: [], 2: [], 9: [] };
  const lines = { 9: Buffer.alloc(0) };
  const received = { stdout: 0, stderr: 0, control: 0, unexpected: 0 };
  const attempted = { stdin: 0, owner: 0 };
  const acknowledged = { stdin: 0, owner: 0 };
  const ended = new Set();
  const pipeClosed = new Set();
  let retainedBytes = 0;
  let failure;
  let child;
  let anchorConfirmed = false;
  let anchorExited = false;
  let anchorLeaseClosed = false;
  let childClosed = false;
  let subject;
  let subjectStatus;
  let ownerReleased = false;
  let signalAttempts = 0;
  let nativeCode;
  let nativeSignal;
  let finalized = false;
  let killTimer;
  let deadline;
  let pipeCount = 0;
  let lateCleanupRecorded = false;
  let pendingWrites = 0;
  const event = (kind, fields = {}) => events.push({ atMs: performance.now() - start, kind, ...fields });
  const accounting = () => ({ received: { ...received }, attempted: { ...attempted }, acknowledged: { ...acknowledged }, retainedOutputBytes: retainedBytes, combinedActualReceivedAndAttempted: Object.values(received).reduce((sum, count) => sum + count, 0) + Object.values(attempted).reduce((sum, count) => sum + count, 0) });
  const argv = ['--noprofile', '--norc', '-c', wrapper, 'negation-supervisor', entry.source, executable];
  save(`case-${entry.id}-startup.json`, {
    time: new Date().toISOString(), entry, sourceSHA256: sha(Buffer.from(entry.source)), argv,
    wrapper, wrapperSHA256: sha(Buffer.from(wrapper)), stdinHex: '', environment, cwd: '/private/tmp', admission,
    fdMap: { 0: 'empty owned subject input; duplicated by supervisor to6', 1: 'subject/descendant stdout', 2: 'subject/descendant stderr', 3: 'unused; closed immediately by Node, never written', 4: 'unused', 5: 'unused, closed by supervisor', 6: 'supervisor stdin duplicate, closed in subject', 7: 'unused, closed by supervisor', 8: 'private supervisor release; closed in subject', 9: 'ANCHOR/SUBJECT/SUBJECT_EXIT lifecycle' },
    timeoutMs: 2000, killAtMs: 1750, maxCombinedBytes: 65536, structuralMaximumBashProcesses: entry.structuralMaximumBashProcesses,
  });
  return new Promise((resolve, reject) => {
    const closeOutgoing = reason => {
      if (anchorLeaseClosed) return;
      anchorLeaseClosed = true;
      event('abort-close-outgoing', { reason });
      for (const fd of [0, 3, 4, 5, 6, 7, 8]) child?.stdio[fd]?.destroy();
    };
    const killAnchoredGroup = () => {
      if (!failure || signalAttempts || !anchorConfirmed || anchorExited || anchorLeaseClosed || ownerReleased || child?.pid === undefined || child.exitCode !== null || child.signalCode !== null) return;
      signalAttempts++;
      try { process.kill(-child.pid, 'SIGKILL'); event('signal-owned-group', { pid: child.pid, signal: 'SIGKILL' }); }
      catch (reason) { event('signal-error', { reason: describe(reason) }); failure.signalError = describe(reason); }
      closeOutgoing('after sole anchored signal attempt');
    };
    const fail = reason => {
      if (finalized) return;
      if (!failure) { failure = describe(reason); event('failure', { reason: failure }); }
      killAnchoredGroup();
    };
    const finish = (cleanupComplete, deadlineExceeded = false) => {
      if (finalized) return;
      finalized = true;
      clearTimeout(killTimer);
      clearTimeout(deadline);
      if (!cleanupComplete) {
        closeOutgoing('incomplete cleanup deadline');
        for (const stream of child?.stdio ?? []) stream?.destroy();
      }
      const result = {
        id: entry.id, name: entry.name, source: entry.source, sourceSHA256: sha(Buffer.from(entry.source)), stdinHex: '',
        supervisorPid: child?.pid, subject, subjectStatus, status: nativeCode ?? null, signal: nativeSignal ?? null,
        stdoutHex: Buffer.concat(output[1]).toString('hex'), stderrHex: Buffer.concat(output[2]).toString('hex'), controlHex: Buffer.concat(output[9]).toString('hex'),
        durationMs: performance.now() - start, failure, deadlineExceeded, cleanupComplete, anchorConfirmed, anchorExited,
        anchorLeaseClosed, ownerReleased, signalAttempts,
        streamEOFs: [...ended], closedPipes: [...pipeClosed], ownedPipeCount: pipeCount, childClosed,
        accounting: accounting(), pendingWrites, events,
      };
      try { save(`case-${entry.id}-result.json`, result); resolve(result); }
      catch (reason) { reject(reason); }
    };
    const maybeFinished = () => {
      if (!childClosed || pipeClosed.size !== pipeCount || pendingWrites !== 0) return;
      if (finalized) {
        if (!lateCleanupRecorded) {
          lateCleanupRecorded = true;
          try { save(`case-${entry.id}-late-cleanup.json`, { time: new Date().toISOString(), durationMs: performance.now() - start, anchorExited, childClosed, closedPipes: [...pipeClosed], accounting: accounting(), noFurtherSignals: true }); }
          catch (reason) { console.error('Late cleanup publication failed', reason); process.exitCode = 1; }
        }
        return;
      }
      if (!failure) {
        if (!ownerReleased || !anchorConfirmed || subject === undefined || subjectStatus === undefined || nativeSignal !== null || nativeCode !== subjectStatus || !ended.has(1) || !ended.has(2) || !ended.has(9) || lines[9].length) fail(new Error('incomplete supervisor protocol'));
      }
      finish(true);
    };
    const guarded = handler => (...args) => { try { handler(...args); } catch (reason) { fail(reason); } };
    const send = (fd, bytes, category, kind) => {
      assert.ok(!finalized && !anchorExited && !childClosed);
      if (category !== 'stdin') assert.ok(anchorConfirmed && subject !== undefined && !anchorLeaseClosed, 'pre-identity or retired send refused');
      assert.ok(accounting().combinedActualReceivedAndAttempted + bytes.length <= 65536, 'outgoing combined budget exceeded');
      attempted[category] += bytes.length;
      event(kind, { fd, hex: bytes.toString('hex'), requestedBytes: bytes.length });
      pendingWrites++;
      try {
        child.stdio[fd].end(bytes, error => {
          pendingWrites--;
          if (error) { event('write-error', { fd, category, reason: describe(error) }); fail(error); }
          else { acknowledged[category] += bytes.length; event('write-acknowledged', { fd, category, bytes: bytes.length }); }
          maybeFinished();
        });
      } catch (reason) { pendingWrites--; throw reason; }
    };
    const advance = () => {
      if (failure) { killAnchoredGroup(); return; }
      if (finalized || anchorExited || childClosed) return;
      if (!ownerReleased && anchorConfirmed && subject !== undefined && subjectStatus !== undefined && ended.has(1) && ended.has(2)) {
        ownerReleased = true;
        send(8, Buffer.from('release\n'), 'owner', 'owner-release');
      }
    };
    const line = bytes => {
        const colon = bytes.indexOf(58);
        assert.ok(colon > 0);
        const digits = bytes.subarray(colon + 1);
        assert.ok(digits.length > 0 && digits.every(byte => byte >= 48 && byte <= 57));
        const value = Number(digits.toString('ascii'));
        assert.ok(Number.isSafeInteger(value) && String(value) === digits.toString('ascii'));
        const tag = bytes.subarray(0, colon).toString('ascii');
        if (tag === 'ANCHOR') { assert.equal(value, child.pid); assert.ok(!anchorConfirmed && !anchorExited && !anchorLeaseClosed); anchorConfirmed = true; }
        else if (tag === 'SUBJECT') { assert.ok(anchorConfirmed && value > 0 && value !== child.pid && subject === undefined); subject = value; }
        else if (tag === 'SUBJECT_EXIT') { assert.ok(anchorConfirmed && subject !== undefined && value >= 0 && value <= 255 && subjectStatus === undefined); subjectStatus = value; }
        else throw new Error('unexpected lifecycle tag');
        event('control-record', { tag, value });
      advance();
    };
    killTimer = setTimeout(() => fail(new Error('execution exceeded 1750ms cleanup-reserving deadline')), Math.max(0, 1750 - (performance.now() - start)));
    deadline = setTimeout(() => {
      fail(new Error('whole case exceeded 2000ms including cleanup'));
      finish(childClosed && pipeClosed.size === pipeCount && pendingWrites === 0, true);
    }, Math.max(0, 2000 - (performance.now() - start)));
    try {
      child = spawn(executable, argv, { cwd: '/private/tmp', env: environment, detached: true, stdio: Array.from({ length: 10 }, () => 'pipe') });
      pipeCount = child.stdio.filter(Boolean).length;
      event('spawn-request', { pid: child.pid });
      child.once('spawn', () => event('spawn', { pid: child.pid }));
      child.once('error', fail);
      child.once('exit', (code, signal) => {
        anchorExited = true;
        nativeCode = code;
        nativeSignal = signal;
        event('anchor-exit', { code, signal });
        if (!ownerReleased && !signalAttempts) { fail(new Error('anchor exited before release; no post-anchor signalling')); closeOutgoing('unexpected anchor exit'); }
      });
      child.once('close', (code, signal) => {
        childClosed = true;
        nativeCode = code;
        nativeSignal = signal;
        event('anchor-close', { code, signal });
        maybeFinished();
      });
      for (const [fd, stream] of child.stdio.entries()) {
        if (!stream) continue;
        stream.on('error', fail);
        stream.once('close', () => { pipeClosed.add(fd); event('pipe-close', { fd }); maybeFinished(); });
        stream.on('data', guarded(chunk => {
          const category = fd === 1 ? 'stdout' : fd === 2 ? 'stderr' : fd === 9 ? 'control' : 'unexpected';
          received[category] += chunk.length;
          if (finalized) return;
          const available = Math.max(0, 65536 - retainedBytes);
          const bytes = Buffer.from(chunk.subarray(0, available));
          if (fd === 1 || fd === 2 || fd === 9) { output[fd].push(bytes); retainedBytes += bytes.length; }
          event('read', { fd, bytes: chunk.length, retainedBytes: bytes.length, hex: bytes.toString('hex') });
          if (accounting().combinedActualReceivedAndAttempted > 65536) { fail(new Error('combined output/control/input budget exceeded')); return; }
          if (category === 'unexpected') { fail(new Error('unexpected descriptor output')); return; }
          if (fd === 9) {
            lines[fd] = Buffer.concat([lines[fd], bytes]);
            let end;
            while ((end = lines[fd].indexOf(10)) !== -1) {
              const complete = lines[fd].subarray(0, end);
              lines[fd] = lines[fd].subarray(end + 1);
              line(complete);
            }
          }
        }));
        stream.once('end', guarded(() => { ended.add(fd); event('eof', { fd }); advance(); }));
      }
      send(0, Buffer.alloc(0), 'stdin', 'stdin-send');
      for (const fd of [3, 4, 5, 6, 7]) { child.stdio[fd].end(); event('unused-input-close', { fd, requestedBytes: 0 }); }
    } catch (reason) {
      fail(reason);
      if (!child) finish(true);
    }
  });
}

const retainedHandles = [];
try {
  save('startup.json', { time: new Date().toISOString(), node: process.execPath, nodeVersion: process.version, argv: process.argv, nativeLaunches: 0, executionRequiresExternalSealDigest: true });
  assert.equal(process.argv.length, 3, 'supply the root-approved seal SHA256');
  const approvedSeal = process.argv[2];
  assert.ok(approvedSeal.length === 64 && [...approvedSeal].every(character => '0123456789abcdef'.includes(character)));
  const sealInput = admittedFile(`${directory}/seal.json`, 32768, true, retainedHandles);
  assert.equal(sealInput.record.sha256, approvedSeal, 'seal digest was not approved');
  const seal = JSON.parse(sealInput.bytes.toString('utf8'));
  assert.equal(seal.format, 1);
  assert.equal(seal.approvalRequired, true);
  const before = authenticate(seal, retainedHandles);
  const proposal = JSON.parse(before.subjects.bytes.toString('utf8'));
  assert.equal(proposal.maximumSubjects, 4);
  assert.equal(before.subjects.record.sha256, before.proposal.record.sha256);
  const subjects = proposal.subjects.map(entry => ({ ...entry, name: entry.purpose, input: '', structuralMaximumBashProcesses: 3 }));
  assert.equal(subjects.length, 4);
  for (const [index, entry] of subjects.entries()) {
    assert.equal(entry.id, index + 1);
    assert.equal(sha(Buffer.from(entry.source)), expectedSources[index]);
    assert.ok(Buffer.byteLength(entry.source) < 4096);
    assert.equal(entry.input, '');
    assert.equal(entry.sourceSHA256, expectedSources[index]);
    assert.equal(entry.executed, false, 'original proposal bytes must remain unchanged');
    assert.equal(entry.structuralMaximumBashProcesses, 3);
    assert.equal(Buffer.byteLength(entry.source), entry.sourceBytes);
    assert.deepEqual(entry.gates, []);
  }
  const recordsOnly = bindings => Object.fromEntries(Object.entries(bindings).map(([name, entry]) => [name, entry.record]));
  save('inventory-before.json', { bindings: recordsOnly(before), seal: sealInput.record, profile: { platform: os.platform(), release: os.release(), version: os.version(), arch: os.arch(), nodeVersion: process.version }, origin: seal.origin, candidateSubjects: 4, candidateSupervisors: 4, retries: 0 });
  const results = [];
  for (const entry of subjects) {
    for (const retained of retainedHandles) {
      const current = fs.fstatSync(retained.handle);
      for (const key of identityKeys) assert.equal(current[key], retained.before[key], `retained ${retained.path} ${key} drift`);
    }
    const admitted = authenticate(seal);
    assert.deepEqual(recordsOnly(admitted), recordsOnly(before), 'prelaunch identity drift');
    const result = await runCase(entry, admitted.supervisor.bytes.toString('utf8'), recordsOnly(admitted));
    const after = authenticate(seal);
    save(`case-${entry.id}-authentication-after.json`, recordsOnly(after));
    assert.deepEqual(recordsOnly(after), recordsOnly(before), 'postlaunch identity drift');
    results.push(result);
    if (result.failure || !result.cleanupComplete || result.deadlineExceeded) {
      save('incomplete.json', { results, stoppedWithoutRetry: true, noLaterCase: true });
      throw new Error(`case ${entry.id} did not qualify; no retries or later launches`);
    }
  }
  const after = authenticate(seal);
  for (const retained of retainedHandles) {
    const current = fs.fstatSync(retained.handle);
    for (const key of identityKeys) assert.equal(current[key], retained.before[key], `final retained ${retained.path} ${key} drift`);
  }
  assert.deepEqual(recordsOnly(after), recordsOnly(before));
