import assert from 'node:assert/strict';
import fs from 'node:fs';
import { createHash } from 'node:crypto';
import { spawn } from 'node:child_process';

const directory = '/private/tmp/jobs53-negation-YOjRP6';
const save = (name, value) => fs.writeFileSync(`${directory}/${name}`, JSON.stringify(value, null, 2) + '\n', { flag: 'wx' });
const retained = [];
const identityKeys = ['dev', 'ino', 'size', 'mode', 'mtimeMs', 'ctimeMs'];
let child;
let observation;

function admit(path, maximum, hold = false, text = false) {
  assert.equal(fs.realpathSync(path), path);
  const before = fs.lstatSync(path);
  assert.ok(before.isFile() && !before.isSymbolicLink() && before.size <= maximum);
  const handle = fs.openSync(path, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  let kept = false;
  try {
    const digest = createHash('sha256');
    const buffer = Buffer.alloc(65536);
    const chunks = [];
    let total = 0;
    for (const key of identityKeys) assert.equal(fs.fstatSync(handle)[key], before[key]);
    while (total < before.size) {
      const count = fs.readSync(handle, buffer, 0, Math.min(buffer.length, before.size - total), null);
      assert.ok(count > 0, 'input shrank');
      total += count;
      digest.update(buffer.subarray(0, count));
      if (text) chunks.push(Buffer.from(buffer.subarray(0, count)));
    }
    assert.equal(fs.readSync(handle, buffer, 0, 1, null), 0, 'input grew');
    for (const after of [fs.fstatSync(handle), fs.lstatSync(path)]) {
      assert.ok(after.isFile() && !after.isSymbolicLink());
      for (const key of identityKeys) assert.equal(after[key], before[key], 'input drift');
    }
    assert.equal(fs.realpathSync(path), path);
    if (hold) { retained.push({ path, handle, before }); kept = true; }
    return { path, sha256: digest.digest('hex'), identity: Object.fromEntries(identityKeys.map(key => [key, before[key]])), text: text ? Buffer.concat(chunks).toString('utf8') : undefined };
  } finally { if (!kept) fs.closeSync(handle); }
}

try {
  save('outer-startup.json', { time: new Date().toISOString(), pid: process.pid, node: process.execPath, nativeRunnerLaunches: 0, approvalRequired: true, noRetries: true, observationTimeoutMs: 20000, timeoutAction: 'record only; retain same live handle; no signals or restart' });
  assert.equal(process.argv.length, 3, 'root-approved seal digest required');
  const approvedSHA = process.argv[2];
  assert.ok(approvedSHA.length === 64 && [...approvedSHA].every(character => '0123456789abcdef'.includes(character)));
  const sealed = admit(`${directory}/seal.json`, 32768, true, true);
  assert.equal(sealed.sha256, approvedSHA);
  const seal = JSON.parse(sealed.text);
  assert.equal(seal.format, 1);
  assert.equal(seal.approvalRequired, true);
  const expectedPaths = {
    runner: `${directory}/capture.mjs`, outer: `${directory}/outer.mjs`, subjects: `${directory}/subjects.json`, supervisor: `${directory}/supervisor.bash`,
    bash: '/private/tmp/safe-bash-gnu-5.3-adjudication.0zMRKT/bash-5.3/bash', node: '/Users/kjopek/.nvm/versions/node/v22.23.2/bin/node',
    proposal: '/private/tmp/jobs53-negation-YOjRP6/proposed-subjects.json', audit: '/private/tmp/jobs53-negation-YOjRP6/final.json',
  };
  const maximum = { runner: 32768, outer: 32768, subjects: 32768, supervisor: 4096, bash: 4194304, node: 268435456, proposal: 32768, audit: 32768 };
  assert.equal(process.execPath, expectedPaths.node);
  const authenticate = hold => Object.fromEntries(Object.entries(expectedPaths).map(([name, path]) => {
    assert.equal(seal.bindings[name].path, path);
    const record = admit(path, maximum[name], hold);
    assert.equal(record.sha256, seal.bindings[name].sha256, `${name} SHA mismatch`);
    return [name, record];
  }));
  const before = authenticate(true);
  assert.equal(before.node.sha256, '18e387c90ab8a8400183e8bdd396376e1e875b91b4c874b894dcade7b35bf572');
  assert.equal(before.bash.sha256, 'a0cfc1af0ff50f6b6e67c638979e2604f1c276c90116937fbaafcabb62ee2b40');
  save('outer-admission.json', { time: new Date().toISOString(), bindings: before, sealSHA256: sealed.sha256 });
  const argv = [expectedPaths.runner, approvedSHA];
  const env = { LC_ALL: 'C', PATH: '/__ordinary_jobs_no_external_commands__' };
  save('outer-launch-request.json', { time: new Date().toISOString(), executable: process.execPath, argv, env, cwd: '/private/tmp', runnerAttempts: 1, maximumSubjects: 4, maximumSupervisors: 4 });
  const output = { stdout: [], stderr: [] };
  const counts = { stdout: 0, stderr: 0 };
  let retainedBytes = 0;
  let spawnError;
  let observedExit;
  child = spawn(process.execPath, argv, { cwd: '/private/tmp', env, stdio: ['ignore', 'pipe', 'pipe'] });
  observation = setTimeout(() => {
    try { save('outer-observation-timeout.json', { time: new Date().toISOString(), pid: child.pid, exitCode: child.exitCode, signalCode: child.signalCode, counts, noSignals: true, noRetry: true, retainSameHandle: true }); }
    catch (reason) { console.error('Observation publication failed', reason); process.exitCode = 1; }
    console.error('Observation deadline reached; same handle retained, no restart or signal.');
  }, 20000);
  for (const name of ['stdout', 'stderr']) child[name].on('data', chunk => {
    counts[name] += chunk.length;
    const bytes = Buffer.from(chunk.subarray(0, Math.max(0, 65536 - retainedBytes)));
    retainedBytes += bytes.length;
    if (bytes.length > 0) output[name].push(bytes);
  });
  child.on('error', reason => { spawnError = { name: reason.name, message: reason.message }; });
  child.once('exit', (code, signal) => { observedExit = { time: new Date().toISOString(), code, signal }; });
  const closed = await new Promise(resolve => child.once('close', (code, signal) => resolve({ code, signal })));
  clearTimeout(observation);
  const stdout = Buffer.concat(output.stdout);
  const stderr = Buffer.concat(output.stderr);
  fs.writeFileSync(`${directory}/outer-stdout.bin`, stdout, { flag: 'wx' });
  fs.writeFileSync(`${directory}/outer-stderr.bin`, stderr, { flag: 'wx' });
  save('outer-result.json', {
    time: new Date().toISOString(), pid: child.pid, ...closed, observedExit, spawnError, counts, retainedBytes,
    combinedReceived: counts.stdout + counts.stderr, outputBudgetExceeded: counts.stdout + counts.stderr > 65536,
    stdoutHex: stdout.toString('hex'), stderrHex: stderr.toString('hex'), runnerLaunchAttempts: 1, outerSignals: 0,
    handle: { closed: true, exitCode: child.exitCode, signalCode: child.signalCode, stdoutDestroyed: child.stdout.destroyed, stderrDestroyed: child.stderr.destroyed },
  });
  const after = authenticate(false);
  save('outer-authentication-after.json', after);
  assert.deepEqual(after, before, 'outer pre/post identity drift');
  const finalSeal = admit(`${directory}/seal.json`, 32768);
  assert.equal(finalSeal.sha256, sealed.sha256);
  assert.deepEqual(finalSeal.identity, sealed.identity);
  for (const entry of retained) for (const key of identityKeys) assert.equal(fs.fstatSync(entry.handle)[key], entry.before[key], 'retained input identity drift');
  assert.equal(spawnError, undefined);
  assert.equal(closed.code, 0);
  assert.equal(closed.signal, null);
  assert.ok(counts.stdout + counts.stderr <= 65536);
  save('outer-qualified.json', { time: new Date().toISOString(), identityStable: true, runnerExit: closed, noRetries: true, noSignals: true });
